import json,statistics,pathlib
p=pathlib.Path('/workspace/shared/gc-direct-evidence');d=json.loads((p/'exploratory.json').read_text());lines=['# Direct bridge exploratory comparison','','Runtime basis: 4959f11 plus public admission fix from d179ec0, isolated harness '+d['provenance']['source_commit']+'.','The additional canonical unknown-ABI receipt rejection guard is absent from this isolated snapshot; valid freshly compiled ABI1 artifacts do not exercise that branch. Three fresh processes per variant/workload; 3 warmup calls then 5 checked calls per sample. This is not the earlier V8 protocol.','','| Case | Variant | median ms/call | three samples ms | timed minor/full per launch | timed RSS (invalid) | median Go heap MiB |','|---|---|---:|---|---|---:|---:|']
for case in ['struct-allocation-access','array-allocation-access','tree-survival']:
 for compiler,mode in [('helper_only','handles'),('helper_only','direct'),('native_direct_reads','direct')]:
  rows=[x for x in d['rows']if x['case']==case and x['compiler']==compiler and x['mode']==mode]
  if any(x['returncode']or'result'not in x for x in rows):lines.append(f'|{case}|{compiler}/{mode}|FAILED|||||');continue
  rs=[x['result']for x in rows];times=[r['samples_ns'][0]/1e6 for r in rs]
  collections=[str(r['after']['MinorCollections']-r['before']['MinorCollections'])+'/'+str(r['after']['FullCollections']-r['before']['FullCollections'])for r in rs]
  lines.append('|'+case+'|'+compiler+'/'+mode+'|'+f'{statistics.median(times):.3f}'+'|'+', '.join(f'{v:.3f}'for v in times)+'|'+', '.join(collections)+'|'+'discarded'+'|'+f'{statistics.median(r["go_after"]["HeapAlloc"]/1048576 for r in rs):.2f}'+'|')
lines+=['','All variants use a configured 64 KiB nursery and 8 MiB old capacity. Direct actually reserves TWO 8 MiB old semispaces plus tracing metadata, promotes all nursery survivors, and uses allocation-heavy exact-root snapshots. Stable handles have different survivor and growth policies. Thus this compares whole experimental collectors, not reference representation alone.','', 'RSS is process high water including Go/compiler/runtime state; Go HeapAlloc is the post-run snapshot, not a dedicated guest-heap measure. Direct scan/copied/promoted-byte counters are unimplemented; zero values are not measured zero work. Invocation and checksum checks are included in samples. No native-fast-path or V8 parity conclusion follows.']
lines += ['', '## Memory audit (separate non-timed processes)', '', 'Timing-process ru_maxrss is INVALID for comparison: the launcher hashed a 48 MiB binary by reading it whole before spawning, causing an inherited 58.5 MiB high-water floor. Those values are retained only in raw evidence and excluded above. The separate three-call audit used a small launcher without this large allocation; its process RSS values follow. Future probe source additionally records /proc/self/status VmHWM/VmRSS and streams hashing.', '', '| Case | Variant | audit peak RSS MiB | Go HeapAlloc MiB |', '|---|---|---:|---:|']
for row in json.loads((p/'audit.json').read_text()):
 r=row['result'];lines.append('|'+r['case']+'|'+row['compiler']+'/'+row['mode']+'|'+f'{r["maxrss_kib"]/1024:.2f}'+'|'+f'{r["go_after"]["HeapAlloc"]/1048576:.2f}'+'|')
(p/'summary.md').write_text('\n'.join(lines)+'\n');print('\n'.join(lines))
